--- landing/index.html ---
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Composition with Red, Blue and Yellow (1930) by Piet Mondrian</title>
<meta name="description" content="Piet Mondrian's Composition with Red, Blue and Yellow, 1930: De Stijl, Neoplasticism and why it matters.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo+Black&family=Archivo:wght@400;600&display=swap" rel="stylesheet">
<style>
:root{--red:#d62718;--blue:#1d3f9a;--yellow:#f4c81f;--black:#111;--white:#f7f5ef;--grey:#d9d8d3;--line:14px}
*{box-sizing:border-box;margin:0}
body{background:var(--black);color:var(--black);font:400 1.05rem/1.55 Archivo,Helvetica,Arial,sans-serif}
a{color:inherit}
.grid{display:grid;gap:var(--line);padding:var(--line);max-width:1200px;margin:0 auto}
.cell{background:var(--white);padding:clamp(1.2rem,3vw,2.4rem)}
h1,h2{font-family:"Archivo Black",Impact,sans-serif;line-height:1.02;letter-spacing:-.01em}
h1{font-size:clamp(2.2rem,6vw,4.6rem)}
h2{font-size:clamp(1.3rem,2.4vw,1.9rem);margin-bottom:.6rem}
.kicker{font-weight:600;text-transform:uppercase;letter-spacing:.14em;font-size:.8rem;margin-bottom:1rem}
.hero{grid-template-columns:2fr 3fr;grid-template-rows:auto auto}
.hero .title{grid-row:span 2}
.red{background:var(--red);color:#fff}.blue{background:var(--blue);color:#fff}.yellow{background:var(--yellow)}.grey{background:var(--grey)}
/* the picture, as described in the fact sheet: big red square top right, small blue bottom left, small yellow bottom right */
.art{aspect-ratio:1;display:grid;gap:var(--line);background:var(--black);padding:var(--line);
 grid-template-columns:1fr 3fr .5fr;grid-template-rows:3fr 1fr .5fr}
.art div{background:var(--white)}
.art .r{grid-column:2/4;grid-row:1/2;background:var(--red)}
.art .b{grid-column:1/2;grid-row:2/4;background:var(--blue)}
.art .y{grid-column:3/4;grid-row:3/4;background:var(--yellow)}
.art .w2{grid-row:2/4}
.artwrap{padding:0;background:var(--black)}
.facts{grid-template-columns:repeat(4,1fr)}
.facts dt{font-weight:600;text-transform:uppercase;letter-spacing:.12em;font-size:.75rem}
.facts dd{font-family:"Archivo Black",sans-serif;font-size:1.25rem;margin-top:.3rem}
.story{grid-template-columns:3fr 2fr 1fr}
.cta{grid-template-columns:1fr 4fr}
.btn{display:inline-block;margin-top:1rem;background:var(--black);color:#fff;padding:.9rem 1.3rem;text-decoration:none;font-weight:600;border:0}
.btn:hover,.btn:focus-visible{background:var(--red);outline:3px solid var(--black)}
ul{padding-left:1.1rem}
footer{color:#bbb;text-align:center;font-size:.8rem;padding:1rem}
@media (max-width:760px){.hero,.facts,.story,.cta{grid-template-columns:1fr}.hero .title{grid-row:auto}.story .spacer,.cta .spacer{display:none}}
</style>
</head>
<body>
<main>
<section class="grid hero" aria-labelledby="t">
  <div class="cell title">
    <p class="kicker">Piet Mondrian, 1930</p>
    <h1 id="t">Composition with Red, Blue and Yellow</h1>
    <p style="margin-top:1rem">Also listed as <em>Composition II in Red, Blue, and Yellow</em>. A few blocks of primary colour, held in place by thick black lines on a white ground.</p>
  </div>
  <div class="cell artwrap" role="img" aria-label="Abstract rendering of the composition: a large red square at top right, a small blue square at bottom left, a small yellow rectangle at bottom right, divided by thick black lines on white">
    <div class="art" aria-hidden="true"><div></div><div class="r"></div><div class="b"></div><div class="w2"></div><div class="y"></div><div></div></div>
  </div>
</section>

<section class="grid facts" aria-label="Key facts">
  <dl class="cell"><dt>Painter</dt><dd>Piet Mondrian</dd><p>Dutch painter, 1872-1944</p></dl>
  <dl class="cell yellow"><dt>Year</dt><dd>1930</dd><p>Oil on canvas</p></dl>
  <dl class="cell"><dt>Movement</dt><dd>De Stijl</dd
